use super::*;
use super::super::snapshot::Ifc2x3Snapshot;
use semio_s_artifact_stdio_contract::part21::parse_part21;
fn fixture(name:&str)->Ifc2x3Snapshot{let source=match name{"placed-extrusion.ifc"=>include_str!("../../../🧪️tests/🧫️fixtures/📐️geometry/placed-extrusion.ifc"),"mapped-extrusion.ifc"=>include_str!("../../../🧪️tests/🧫️fixtures/📐️geometry/mapped-extrusion.ifc"),"tetrahedron-brep.ifc"=>include_str!("../../../🧪️tests/🧫️fixtures/📐️geometry/tetrahedron-brep.ifc"),"complex-item.ifc"=>include_str!("../../../🧪️tests/🧫️fixtures/📐️geometry/complex-item.ifc"),"complex-product.ifc"=>include_str!("../../../🧪️tests/🧫️fixtures/📐️geometry/complex-product.ifc"),_=>panic!("unknown fixture")};Ifc2x3Snapshot{document:parse_part21(source).unwrap(),..Ifc2x3Snapshot::default()}}
#[semio_framework_async_macros::async_test]
async fn neutral_source_geometry_matches_independently_verified_measures(){let cases=semio_framework_pack_json::parse(include_str!("../../../🧪️tests/🧫️fixtures/📐️geometry/🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for row in cases["cases"].as_array().unwrap(){let snapshot=fixture(row["file"].as_str().unwrap());let scene=project(&snapshot);assert_eq!(scene.status,GeometryStatus::Complete);assert_eq!(scene.meshes.len() as u64,row["meshes"].as_u64().unwrap());if let Some(reason)=row.get("issue"){assert!(scene.issues.iter().any(|issue|issue.reason==reason.as_str().unwrap()));continue;}assert!(scene.issues.is_empty());let mesh=&scene.meshes[0];assert_eq!(mesh.product,row["product"].as_str().unwrap().parse::<u64>().unwrap());assert_eq!(mesh.representation,row["representation"].as_str().unwrap().parse::<u64>().unwrap());assert_eq!(mesh.vertices.len() as u64,row["vertices"].as_u64().unwrap());assert_eq!(mesh.triangles.len() as u64,row["triangles"].as_u64().unwrap());let bounds=scene.bounds().unwrap();for side in 0..2{for axis in 0..3{assert!((bounds[side][axis]-row["bounds"][side][axis].as_f64().unwrap()).abs()<1e-9);}}let volume:f64=mesh.triangles.iter().map(|ids|{let[a,b,c]=ids.map(|id|mesh.vertices[id as usize]);(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6.}).sum();assert!((volume.abs()-row["volume"].as_f64().unwrap()).abs()<1e-9);}}
#[semio_framework_async_macros::async_test]
async fn original_caller_controls_projection(){let snapshot=fixture("placed-extrusion.ifc");for decision in [GeometryControl::Cancel,GeometryControl::Limit]{let mut calls=0;let scene=project_controlled(&snapshot,GeometryLimits::default(),&mut |_|{calls+=1;if calls==10{decision}else{GeometryControl::Continue}});assert_eq!(calls,10);assert!(scene.meshes.is_empty());assert_eq!(scene.status,if decision==GeometryControl::Cancel{GeometryStatus::Cancelled}else{GeometryStatus::Limited});}let scene=project_controlled(&snapshot,GeometryLimits{work:1,..GeometryLimits::default()},&mut |_|GeometryControl::Continue);assert_eq!(scene.status,GeometryStatus::Limited);assert!(scene.meshes.is_empty());}
#[semio_framework_async_macros::async_test]
async fn official_architecture_uses_real_graph_geometry(){let snapshot=Ifc2x3Snapshot{document:parse_part21(include_str!("../../../🧪️tests/🧫️fixtures/📐️geometry/official-architecture.ifc")).unwrap(),..Ifc2x3Snapshot::default()};let scene=project(&snapshot);assert_eq!(scene.status,GeometryStatus::Complete);assert!(!scene.meshes.is_empty());assert!(scene.meshes.iter().all(|m|snapshot.document.instances.iter().any(|e|e.id==m.product)));}

#[semio_framework_async_macros::async_test]
async fn cancelled_payloads_hide_a_complete_product_prefix(){let mut snapshot=fixture("placed-extrusion.ifc");let mut product=snapshot.document.instances.iter().find(|e|e.id==17).unwrap().clone();product.id=100;snapshot.document.instances.push(product);let total=project(&snapshot).work;let scene=project_controlled(&snapshot,GeometryLimits::default(),&mut |p|if p.work>=total-1{GeometryControl::Cancel}else{GeometryControl::Continue});assert_eq!(scene.status,GeometryStatus::Cancelled);assert_eq!(scene.meshes.len(),1);assert_eq!(scene.meshes_json(),"[]");assert_eq!(scene.instances_json(),"[]");assert_eq!(scene.camera(),([1.5,-1.5,1.2],[0.;3]));}

#[semio_framework_async_macros::async_test]
async fn native_ifc2x3_closed_opening_uses_shared_solid_operation(){let snapshot=Ifc2x3Snapshot{document:parse_part21(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/placed-opening-2x3.ifc")).unwrap(),..Ifc2x3Snapshot::default()};let scene=project(&snapshot);assert_eq!(scene.status,GeometryStatus::Complete);assert_eq!(scene.meshes.len(),1,"{:?}",scene.issues);let mesh=&scene.meshes[0];let volume:f64=mesh.triangles.iter().map(|ids|{let[a,b,c]=ids.map(|i|mesh.vertices[i as usize]);(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6.}).sum();assert!((volume-48.).abs()<1e-8);assert_eq!(mesh.product,17);}

#[semio_framework_async_macros::async_test]
async fn native_ifc2x3_regularized_boolean_results_share_original_graph_semantics(){let source=include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/boolean-result.ifc").replace("'IFC4'","'IFC2X3'");for(operation,expected)in [("DIFFERENCE",48.),("UNION",72.),("INTERSECTION",16.)]{let text=source.replace(".DIFFERENCE.",&format!(".{operation}."));let snapshot=Ifc2x3Snapshot{document:parse_part21(&text).unwrap(),..Ifc2x3Snapshot::default()};let scene=project(&snapshot);assert_eq!(scene.status,GeometryStatus::Complete);assert_eq!(scene.meshes.len(),1,"{:?}",scene.issues);let mesh=&scene.meshes[0];assert_eq!(mesh.product,17);assert_eq!(mesh.representation,11);let volume:f64=mesh.triangles.iter().map(|ids|{let[a,b,c]=ids.map(|i|mesh.vertices[i as usize]);(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6.}).sum();assert!((volume-expected).abs()<1e-8);}}

#[semio_framework_async_macros::async_test]
async fn native_ifc2x3_csg_wrapper_block_and_rounded_profile_use_shared_geometry(){for(source,expected)in [(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/csg-wrapper.ifc"),48.),(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/block.ifc"),24.),(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/rounded-rectangle.ifc"),(12.+36.*(std::f64::consts::PI/36.).sin())*4.)]{let text=source.replace("'IFC4'","'IFC2X3'");let snapshot=Ifc2x3Snapshot{document:parse_part21(&text).unwrap(),..Ifc2x3Snapshot::default()};let scene=project(&snapshot);assert_eq!(scene.status,GeometryStatus::Complete);assert!(scene.issues.is_empty(),"{:?}",scene.issues);assert_eq!(scene.meshes.len(),1);let mesh=&scene.meshes[0];let volume:f64=mesh.triangles.iter().map(|ids|{let[a,b,c]=ids.map(|i|mesh.vertices[i as usize]);(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6.}).sum();assert!((volume-expected).abs()<1e-8);}}

#[semio_framework_async_macros::async_test]
async fn native_ifc2x3_plane_clipping_uses_original_material_side_and_affine_normals(){for(source,expected)in [(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/plane-clipping.ifc"),32.),(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/holed-plane-clipping.ifc"),24.),(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/nested-plane-clipping.ifc"),16.),(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/mapped-plane-clipping.ifc"),192.),(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/reflected-plane-clipping.ifc"),32.)]{let text=source.replace("'IFC4'","'IFC2X3'");let snapshot=Ifc2x3Snapshot{document:parse_part21(&text).unwrap(),..Ifc2x3Snapshot::default()};let scene=project(&snapshot);assert_eq!(scene.status,GeometryStatus::Complete);assert!(scene.issues.is_empty(),"{:?}",scene.issues);assert_eq!(scene.meshes.len(),1);let mesh=&scene.meshes[0];let volume:f64=mesh.triangles.iter().map(|ids|{let[a,b,c]=ids.map(|i|mesh.vertices[i as usize]);(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6.}).sum();assert!((volume-expected).abs()<1e-8);}}

#[test]
fn retained_placed_primitives_resume_from_original_caller_grants(){for(source,expected)in [(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/block.ifc").to_owned(),24.),(include_str!("../../../../../../../📐️geometry/🧊️boolean/🧪️tests/rounded-rectangle.ifc").replace("IFCROUNDEDRECTANGLEPROFILEDEF(.AREA.,$,#9,4.,4.,1.)","IFCRECTANGLEPROFILEDEF(.AREA.,$,#9,4.,4.)"),64.)]{let text=source.replace("'IFC4'","'IFC2X3'");let doc=semio_s_artifact_stdio_contract::part21::parse_part21(&text).unwrap();let graph=Ifc2x3GeometryGraph(&doc);super::shared::preparation::tests::verify_graph(&graph,2,text.len(),expected);}}
